}
.section-desc {
  font-size: 1.05rem;
  color: var(--text-secondary);
  max-width: 640px;
  line-height: 1.7;
}

/* ===== HERO SECTIONS ===== */
.hero {
  position: relative;
  padding: 8rem 0 5rem;
